// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 depositAmount, uint256 reenterAmount) public {
        depositAmount = bound(depositAmount, 1, 10 ether);
        reenterAmount = bound(reenterAmount, 1, 10 ether);

        Attacker attacker = new Attacker(c, reenterAmount);
        vm.deal(address(attacker), depositAmount + reenterAmount + 1 ether);

        // Attacker deposits depositAmount, then withdraws; during the withdraw's
        // external call its receive() re-enters addToBalance with reenterAmount.
        try attacker.go(depositAmount) {
            // completed
        } catch {
            // reverted (reference contract blocks the reentrant deposit)
        }

        // General rule: the contract's total ether holdings always equal the
        // sum of credited user balances (here, the single actor's balance).
        assertTrue(address(c).balance == c.getBalance(address(attacker)));
    }
}

contract Attacker {
    Reentrance c;
    uint256 reAmt;
    bool doReenter;

    constructor(Reentrance _c, uint256 amt) {
        c = _c;
        reAmt = amt;
    }

    function go(uint256 d) external {
        c.addToBalance{value: d}();
        doReenter = true;
        c.withdrawBalance();
    }

    receive() external payable {
        if (doReenter) {
            doReenter = false;
            c.addToBalance{value: reAmt}();
        }
    }
}
